import { Component, OnInit } from '@angular/core';
import { Interview } from 'src/app/auth/Models/Interview';
import { InterviewService } from 'src/app/service/interview/interview.service';

@Component({
  selector: 'app-interviews',
  templateUrl: './interviews.component.html',
  styleUrls: ['./interviews.component.css']
})
export class InterviewsComponent implements OnInit {

  id: number = Number(localStorage.getItem('id'));

  interviews: Interview[] = [];
  activeTab: 'ALL' | 'SCHEDULED' | 'COMPLETED' | 'CANCELLED' = 'ALL';

  constructor(private interviewService: InterviewService) {}

  ngOnInit(): void {
    this.getInterviews();
  }

  getInterviews() {
    this.interviewService.getInterviewsByCompany(this.id).subscribe({
      next: (res) => this.interviews = res,
      error: (err) => console.log(err)
    });
  }

  setTab(tab: 'ALL' | 'SCHEDULED' | 'COMPLETED' | 'CANCELLED') {
    this.activeTab = tab;
  }

  get filteredInterviews(): Interview[] {
    if (this.activeTab === 'ALL') return this.interviews;
    if (this.activeTab === 'SCHEDULED') {
      return this.interviews.filter(i => i.status === 'SCHEDULED' || i.status === 'RESCHEDULED');
    }
    return this.interviews.filter(i => i.status === this.activeTab);
  }

  statusChipClass(status: string): string {
    switch (status) {
      case 'COMPLETED': return 'chip-completed';
      case 'CANCELLED': return 'chip-canceled';
      case 'RESCHEDULED': return 'chip-pending';
      default: return 'chip-open';
    }
  }

  cancelInterview(id: number) {
    if (!confirm('Cancel this interview?')) return;

    this.interviewService.cancelInterview(id).subscribe({
      next: () => this.getInterviews(),
      error: (err) => console.log(err)
    });
  }
}
<div class="page">
<app-header variant="company"></app-header>
<div class="app-shell">
<app-sidebar variant="company"></app-sidebar>
<main class="main-wide">

<div class="section-head"><h2>Interviews</h2></div>
<div class="tab-row">
  <span class="tab" [class.active]="activeTab === 'ALL'" (click)="setTab('ALL')">All</span>
  <span class="tab" [class.active]="activeTab === 'SCHEDULED'" (click)="setTab('SCHEDULED')">Scheduled</span>
  <span class="tab" [class.active]="activeTab === 'COMPLETED'" (click)="setTab('COMPLETED')">Completed</span>
  <span class="tab" [class.active]="activeTab === 'CANCELLED'" (click)="setTab('CANCELLED')">Cancelled</span>
</div>

<div class="table-wrap">
  <table>
    <thead><tr><th>Candidate</th><th>Role</th><th>Scheduled</th><th>Mode</th><th>Status</th><th></th></tr></thead>
    <tbody>
      <tr *ngFor="let iv of filteredInterviews">
        <td>{{ iv.jobSeekerName }}</td>
        <td>{{ iv.jobTitle }}</td>
        <td>{{ iv.scheduledAt | date:'medium' }}</td>
        <td>{{ iv.mode }}</td>
        <td><span class="chip" [ngClass]="statusChipClass(iv.status)">{{ iv.status }}</span></td>
        <td class="actions">
          <a [routerLink]="['/company/company/applicant', iv.applicationId]">View</a>
          <a (click)="cancelInterview(iv.id)" style="cursor:pointer;" *ngIf="iv.status === 'SCHEDULED' || iv.status === 'RESCHEDULED'">Cancel</a>
        </td>
      </tr>
      <tr *ngIf="filteredInterviews.length === 0">
        <td colspan="6" style="text-align:center;color:var(--muted);padding:24px;">No interviews here yet.</td>
      </tr>
    </tbody>
  </table>
</div>

</main>
</div>
</div>
